// Load existing controls when component mounts
useEffect(() => {
  const loadExistingControls = async () => {
    if (!currentProject?.id || !filteredAssessments?.length) return;

    try {
      console.log('Loading controls for assessments:', filteredAssessments);

      // Get all assessment IDs
      const assessmentIds = filteredAssessments
        .filter(assessment => assessment?.id)
        .map(assessment => assessment.id);

      if (!assessmentIds.length) {
        console.log('No valid assessment IDs to query');
        return;
      }

      // Load all controls at once
      const { data: controls, error } = await supabase
        .from('hira_risk_controls')
        .select('*')
        .in('assessment_id', assessmentIds);

      if (error) throw error;

      // Map controls to form fields
      filteredAssessments.forEach((assessment, index) => {
        const control = controls?.find(c => c.assessment_id === assessment.id);
        if (control) {
          setValue(`controls.${index}.additional_mitigation`, control.additional_mitigation || '');
          setValue(`controls.${index}.risk_owner`, control.risk_owner || '');
          setValue(`controls.${index}.target_date`, control.target_date || '');
          setValue(`controls.${index}.date_implemented`, control.date_implemented || '');
        }
      });
    } catch (error) {
      console.error('Error loading existing controls:', error);
    }
  };

  loadExistingControls();
}, [currentProject?.id, filteredAssessments, setValue]);

const handleFormSubmit = async (data) => {
  try {
    console.log('Submitting form data:', data);

    // Get all assessment IDs
    const assessmentIds = data.controls
      .filter(control => control?.assessment_id)
      .map(control => control.assessment_id);

    // Get existing controls
    const { data: existingControls } = await supabase
      .from('hira_risk_controls')
      .select('*')
      .in('assessment_id', assessmentIds);

    // Update or create controls using the service methods
    const savedControls = await Promise.all(
      data.controls.map(async control => {
        if (!control.assessment_id) {
          console.warn('Control missing assessment_id:', control);
          return null;
        }

        const existingControl = existingControls?.find(
          ec => ec.assessment_id === control.assessment_id
        );

        try {
          if (existingControl) {
            return await controlService.updateRiskControl(existingControl.id, control);
          } else {
            return await controlService.createRiskControl(control.assessment_id, control);
          }
        } catch (error) {
          console.error('Error saving control:', error);
          return null;
        }
      })
    );

    // Filter out any null results from failed saves
    const validSavedControls = savedControls.filter(control => control !== null);

    // Update store
    await setStepData(4, { controls: validSavedControls });
  } catch (error) {
    console.error('Error saving risk controls:', error);
  }
};
